/// <summary>
/// 原密码验证
/// </summary>
/// <param name="context">请求信息</param>
public void CheckPwd0(HttpContext context)
{
    string userCode = context.Request["userCode"];
    string pwd = context.Request["pwd"];

    //预留，日志扩展信息
    LogMessageExtend extend = new LogMessageExtend() { USER_NAME = userCode, REQUEST_SOURCE = GetClientIP() };
    try
    {
        var org = new OrgChart();
        User user;
        string errorMsg = "";
        org.GetUser(userCode, out user, out errorMsg);
        if (user != null)
        {
            if (SecurityHelper.MD5(pwd) == user.USER_PWD)
            {
                context.Response.Write("{errorMsg:'success',data:''}");
            }
            else
            {
                context.Response.Write("{errorMsg:'error',data:'原密码不正确！'}");
            }
        }
        else
        {
            context.Response.Write("{errorMsg:'error',data:'用户信息不存在！'}");
        }
    }
    catch (Exception ex)
    {
        LoggerUtility.WriteExtend("忘记密码管理", "原密码验证失败", ex.Message, extend, LogType.Error);
