```csharp
/// <summary>
/// 校验密码复杂度（服务端），符合返回null，不符合返回提示信息
/// </summary>
private string CheckPwdRule(string pwd)
{
    string DefaultPWDRule = ConfigManager.GetAttributeValue("Portal", "DefaultPWDRule");
    string PWDRuleTitle = ConfigManager.GetAttributeValue("Portal", "PWDRuleTitle");
    if (string.IsNullOrEmpty(DefaultPWDRule) || DefaultPWDRule == "无")
    {
        return null;
    }
    if (DefaultPWDRule == "自定义")
    {
        string CustomPWDRule = ConfigManager.GetAttributeValue("Portal", "CustomPWDRule");
        if (string.IsNullOrEmpty(CustomPWDRule))
        {
            return "当前自定义密码策略配置(CustomPWDRule)有误，请联系系统管理员！";
        }
        return CheckPWDRule(pwd, CustomPWDRule) ? null : PWDRuleTitle;
    }
    return CheckPWDRule(pwd, DefaultPWDRule) ? null : PWDRuleTitle;
}
```

