cd DACHKJ.Portal.Web/bin && python -c "
data = open('Dachkj.Utility.FAL.dll','rb').read()
# extract utf-16le strings (runs of printable chars)
import re
results = []
i = 0
while i < len(data) - 1:
    j = i
    while j < len(data) - 1:
        b = data[j]; b2 = data[j+1]
        if b == 0 and b2 == 0:
            break
        if 0x20 <= b < 0x7f and b2 == 0:
            j += 2
        elif 0x4e00 <= (b | (b2 << 8)) <= 0x9fff:
            j += 2
        elif b2 == 0 and b < 0x7f:
            j += 2
        else:
            break
    if j - i >= 8:  # min 4 chars
        s = data[i:j].decode('utf-16-le')
        results.append(s)
    i = max(j, i+2)
for s in results:
    if ('异常' in s or 'xml' in s.lower() or '查询' in s or 'XML' in s):
        print(repr(s))
"

